CustomField.formula:
IF(
    OR(
        ISBLANK(Login_Time__c),
        ISBLANK(Logout_Time__c)
    ),
    "",
    TEXT(
        FLOOR(
            (Logout_Time__c - Login_Time__c) / 3600000
        )
    ) & " hrs " &
    TEXT(
        FLOOR(
            MOD( (Logout_Time__c - Login_Time__c), 3600000 ) / 60000
        )
    ) & " mins"
)
